#include <cstddef>
#include <cstdint>
#include <cstdlib>

void* aligned_malloc(std::size_t size, std::size_t align) {
  if (align == 0 || (align & (align - 1)) != 0) return nullptr;  // power of 2
  if (align < alignof(void*)) align = alignof(void*);
  const std::size_t extra = align - 1 + sizeof(void*);
  if (size > SIZE_MAX - extra) return nullptr;                    // overflow
  void* raw = std::malloc(size + extra);
  if (!raw) return nullptr;
  std::uintptr_t start = reinterpret_cast<std::uintptr_t>(raw) + sizeof(void*);
  std::uintptr_t aligned = (start + align - 1) & ~static_cast<std::uintptr_t>(align - 1);
  reinterpret_cast<void**>(aligned)[-1] = raw;   // stash original pointer
  return reinterpret_cast<void*>(aligned);
}

void aligned_free(void* p) {
  if (p) std::free(reinterpret_cast<void**>(p)[-1]);
}

